paragraph.math:
$$\begin{array}{rcll}
  {\int\frac{\mathit{dQ}}{Q}} & = & {\int{kdt}} & \\
  {\ln|Q|} & = & {kt + C_{1}} & \\
  |Q| & = & {e^{kt + C_{1}} = e^{\mathit{kt}}e^{C_{1}} = C_{2}e^{\mathit{kt}}} & {\qquad{C_{2} = e^{C_{1}}}} \\
  Q & = & \mathit{Ce}^{\mathit{kt}} & {\qquad{C = \pm C_{2}}}
  \end{array}$$
